import{_ as e,o as a,c as i,ao as s}from"./chunks/framework.DUdA5YZf.js";const p=JSON.parse('{"title":"Dual numbers: BLAS-1 for forward-mode AD","description":"","frontmatter":{},"headers":[],"relativePath":"dual.md","filePath":"dual.md","lastUpdated":null}'),o={name:"dual.md"};function d(l,t,n,r,h,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="Dual-numbers:-BLAS-1-for-forward-mode-AD" tabindex="-1">Dual numbers: BLAS-1 for forward-mode AD <a class="header-anchor" href="#Dual-numbers:-BLAS-1-for-forward-mode-AD" aria-label="Permalink to &quot;Dual numbers: BLAS-1 for forward-mode AD {#Dual-numbers:-BLAS-1-for-forward-mode-AD}&quot;">​</a></h1><p>Status: <strong>all three steps implemented</strong> (2026-09-12; see &quot;Implementation notes&quot; at the end). This page records the design, the measurements it rests on, and the decisions taken — including the ones that closed off tempting alternatives.</p><p><code>ForwardDiff.Dual{Tag,V,1}</code> and <code>Complex{V}</code> have <strong>byte-identical memory layout</strong>, so PureBLAS can serve forward-mode AD from the same SIMD machinery it uses for complex. Nothing else in the Julia ecosystem ships a BLAS optimised for array-of-structs dual numbers; ForwardDiff users currently fall through to scalar loops because <code>Dual</code> is not a <code>BlasFloat</code>.</p><h2 id="The-layout-fact-this-rests-on" tabindex="-1">The layout fact this rests on <a class="header-anchor" href="#The-layout-fact-this-rests-on" aria-label="Permalink to &quot;The layout fact this rests on {#The-layout-fact-this-rests-on}&quot;">​</a></h2><p>Verified 2026-09-12 on Julia 1.13.0 / ForwardDiff:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Dual{Nothing,Float64,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ComplexF64)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">reinterpret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Float64, [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dual{Nothing}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dual{Nothing}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Same as <code>reinterpret(Float64, ComplexF64[1+2im, 3+4im])</code>. <code>Dual</code> is <code>value::V</code> + <code>partials::Partials{N,V}</code> wrapping an <code>NTuple{N,V}</code>, so at <code>N = 1</code> it is exactly an interleaved pair. Every load, store, stride, alignment and in-lane shuffle transfers unchanged.</p><p>The extension asserts this at load time (<code>sizeof == 16 &amp;&amp; fieldoffset(..., 2) == 8</code>), so a future ForwardDiff layout change becomes a load error rather than silent garbage.</p><h2 id="The-trap-the-layout-creates" tabindex="-1">⛔ The trap the layout creates <a class="header-anchor" href="#The-trap-the-layout-creates" aria-label="Permalink to &quot;⛔ The trap the layout creates {#The-trap-the-layout-creates}&quot;">​</a></h2><p>Because the layouts are bit-identical it is tempting to <code>reinterpret</code> a <code>Vector{Dual}</code> to <code>Vector{ComplexF64}</code> and call the complex kernel. <strong>That is wrong wherever two elements multiply.</strong></p><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;">product</th><th style="text-align:right;">real part / value</th></tr></thead><tbody><tr><td style="text-align:right;">complex</td><td style="text-align:right;"><code>(a+bi)(c+di)</code></td><td style="text-align:right;"><code>ac − bd</code></td></tr><tr><td style="text-align:right;">dual</td><td style="text-align:right;"><code>(a+bε)(c+dε)</code></td><td style="text-align:right;"><code>ac</code> (ε² = 0)</td></tr></tbody></table><p>Reinterpreting silently subtracts <code>bd</code> from the value. It is only valid where no element × element product occurs: <code>copy</code>, <code>swap</code>, <code>axpy</code> with a <strong>real</strong> alpha, <code>scal</code> by a <strong>real</strong> alpha.</p><p>The ε²-leak test exists to catch exactly this: run <code>dot(x,x)</code> with partials ~<code>1e155</code> so <code>Σ x_p²</code> overflows. The value must stay finite and the partial must equal <code>2 Σ x_v x_p</code>. A reinterpreted complex kernel fails it.</p><h2 id="Dual-needs-3-multiplies,-complex-needs-4-does-not-survive-into-SIMD" tabindex="-1">⛔ &quot;Dual needs 3 multiplies, complex needs 4&quot; does not survive into SIMD <a class="header-anchor" href="#Dual-needs-3-multiplies,-complex-needs-4-does-not-survive-into-SIMD" aria-label="Permalink to &quot;⛔ &quot;Dual needs 3 multiplies, complex needs 4&quot; does not survive into SIMD {#&quot;Dual-needs-3-multiplies,-complex-needs-4&quot;-does-not-survive-into-SIMD}&quot;">​</a></h2><p>The scalar op counts are real — dual multiply is <code>ac</code>, <code>ad + bc</code>; complex is <code>ac − bd</code>, <code>ad + bc</code> — but in the interleaved swap-adjacent form both algebras are the same two FMAs and one shuffle:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">muladd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">shuffle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x), sgn, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">muladd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, arv, y))</span></span></code></pre></div><p>with <code>sgn = [−b, +b, …]</code> for complex and <code>[0, +b, …]</code> for dual. The second FMA runs over the whole vector either way. <strong>The dual advantage is a scalar-op-count fact, not a kernel fact</strong>, and the design does not claim otherwise. (As shipped, the dual arm pairs <code>[0, +b, …]</code> with the <strong>duplicate-even</strong> shuffle rather than the swap — same op count, and it keeps the <code>0·</code> off the partial lane; see the NaN note under <code>dupEven</code>.)</p><h2 id="Measured:-where-dual-actually-loses-today" tabindex="-1">Measured: where dual actually loses today <a class="header-anchor" href="#Measured:-where-dual-actually-loses-today" aria-label="Permalink to &quot;Measured: where dual actually loses today {#Measured:-where-dual-actually-loses-today}&quot;">​</a></h2><p>Dual GB/s ÷ the complex twin&#39;s GB/s on identical bytes, through the real PureBLAS entries (wintermute, Julia 1.13.0, scratch env — adequate for an order-of-magnitude decision, <strong>not</strong> a gate number):</p><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">n=1e3</th><th style="text-align:right;">n=1e4</th><th style="text-align:right;">n=1e5</th><th style="text-align:right;">n=1e6</th></tr></thead><tbody><tr><td style="text-align:right;">axpy</td><td style="text-align:right;">0.82</td><td style="text-align:right;">0.80</td><td style="text-align:right;">1.03</td><td style="text-align:right;">1.00</td></tr><tr><td style="text-align:right;">scal</td><td style="text-align:right;">0.69</td><td style="text-align:right;">0.65</td><td style="text-align:right;">0.77</td><td style="text-align:right;">0.99</td></tr><tr><td style="text-align:right;">dot</td><td style="text-align:right;">0.37</td><td style="text-align:right;">0.34</td><td style="text-align:right;">0.49</td><td style="text-align:right;">0.92</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;">0.21</td><td style="text-align:right;">0.18</td><td style="text-align:right;">0.23</td><td style="text-align:right;">0.61</td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">0.37</td><td style="text-align:right;">0.29</td><td style="text-align:right;">0.29</td><td style="text-align:right;">0.36</td></tr><tr><td style="text-align:right;"><strong>nrm2</strong></td><td style="text-align:right;"><strong>0.07</strong></td><td style="text-align:right;"><strong>0.06</strong></td><td style="text-align:right;"><strong>0.08</strong></td><td style="text-align:right;"><strong>0.20</strong></td></tr></tbody></table><p><code>nrm2</code> is flat at <strong>4.8 GB/s at every n</strong> — 13–16× slower than complex. Flat in <code>n</code> means it is not memory-bound: neither fast branch applies (<code>_simd1</code> is <code>BlasReal</code>-only, <code>_cplx_re</code> is <code>Complex</code>-only), so it falls to the <code>lassq</code> scaling loop, <code>_nrm2_acc</code> per element with a division and branches.</p><p><strong>This is what sets the scope.</strong> The reductions are the prize; <code>axpy</code>/<code>scal</code> converge to parity past L2 and are only 20–35% down in cache.</p><h2 id="The-dupEven-formulation" tabindex="-1">The <code>dupEven</code> formulation <a class="header-anchor" href="#The-dupEven-formulation" aria-label="Permalink to &quot;The \`dupEven\` formulation {#The-dupEven-formulation}&quot;">​</a></h2><p>Rather than the swap-adjacent shuffle, dual reductions use an <strong>in-lane duplicate-even</strong> shuffle <code>(0,0,2,2,…)</code>, so <code>dupEven(v) = [x_v, x_v]</code> per pair. Same cost class as the swap, and it lands the useful quantity in both lanes:</p><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">body</th><th style="text-align:right;">parity fold gives</th></tr></thead><tbody><tr><td style="text-align:right;">nrm2</td><td style="text-align:right;"><code>acc = muladd(v, dupEven(v), acc)</code></td><td style="text-align:right;"><code>[Σ x_v², Σ x_v·x_p]</code> — one FMA, no wasted lanes</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;"><code>acc += flipsign(v, dupEven(v))</code></td><td style="text-align:right;"><code>[Σ|x_v|, Σ sign(x_v)·x_p]</code> — no blend</td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">magnitude <code>= abs(dupEven(v))</code></td><td style="text-align:right;">value magnitude broadcast to both lanes</td></tr></tbody></table><p><code>flipsign</code> uses the sign <strong>bit</strong>, matching ForwardDiff&#39;s <code>abs</code> derivative (<code>signbit(x) ? -1 : 1</code>) bit-for-bit at ±0.0.</p><p><code>dupEven</code> also removes a NaN hazard. With <code>sgn = [0, b, …]</code> the even lane computes <code>t + 0·x_p</code>, so an infinite partial makes <code>0·Inf = NaN</code> poison the <strong>value</strong>. Putting the <code>0·</code> on the value lane instead means it only misbehaves when the value is already <code>Inf</code>, where the scalar result is <code>Inf</code> too.</p><h2 id="Per-op-decisions" tabindex="-1">Per-op decisions <a class="header-anchor" href="#Per-op-decisions" aria-label="Permalink to &quot;Per-op decisions {#Per-op-decisions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">dual implementation</th><th style="text-align:right;">semantics</th></tr></thead><tbody><tr><td style="text-align:right;">copy, swap</td><td style="text-align:right;">route to <code>_copy_simd!</code>/<code>_swap_simd!</code> over 2n reals</td><td style="text-align:right;">no arithmetic</td></tr><tr><td style="text-align:right;">axpy, scal</td><td style="text-align:right;">shared tagged body; real-alpha bypass to the real kernel over 2n</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;">dotu</td><td style="text-align:right;">shared body, per-algebra epilogue</td><td style="text-align:right;">value <code>= Σ x_v y_v</code>; the <code>Σ x_p y_p</code> lane is the ε² term and is <strong>discarded</strong></td></tr><tr><td style="text-align:right;">dotc</td><td style="text-align:right;">identical to dotu</td><td style="text-align:right;"><code>Dual &lt;: Real</code> and ForwardDiff defines no <code>conj</code>, so <code>conj(::Real) = x</code>. <strong>The ring involution <code>a − bε</code> is wrong for AD</strong>: <code>dot(x,x)</code> would give <code>Σa²</code> with a zero partial, i.e. <code>d‖x‖²/dx = 0</code></td></tr><tr><td style="text-align:right;">nrm2</td><td style="text-align:right;">standalone; <code>dupEven</code> body, not the complex <code>_sumsq_simd</code></td><td style="text-align:right;"><code>√(Σx_v²) + (Σ x_v x_p / ‖x_v‖) ε</code>. Fast path guards <code>isfinite(ss) &amp;&amp; !iszero(ss) &amp;&amp; isfinite(sp)</code>; falls back to the existing Dual lassq loop only on overflow</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;">standalone; <code>dupEven</code> + <code>flipsign</code></td><td style="text-align:right;">value <code>Σ|x_v|</code>, partial <code>Σ flipsign(x_p, x_v)</code></td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">magnitude functor on the existing argmax scaffold</td><td style="text-align:right;"><strong>argmax of <code>|value|</code>, first occurrence on ties</strong> — see below</td></tr></tbody></table><p><code>N ≠ 1</code>, nested duals, and non-<code>BlasReal</code> <code>V</code> miss the routing predicate and take the generic scalar loop unchanged. Generalising to <code>N &gt; 1</code> is a different layout (stride <code>N+1</code>, not a pair) and is out of scope.</p><h3 id="iamax:-a-deliberate,-user-visible-semantics-change" tabindex="-1">iamax: a deliberate, user-visible semantics change <a class="header-anchor" href="#iamax:-a-deliberate,-user-visible-semantics-change" aria-label="Permalink to &quot;iamax: a deliberate, user-visible semantics change {#iamax:-a-deliberate,-user-visible-semantics-change}&quot;">​</a></h3><p><code>abs(::Dual)</code> returns a <strong>Dual</strong>, and ForwardDiff&#39;s <code>isless</code> is lexicographic — value first, then partials. So when two elements have equal magnitude, the current generic loop breaks the tie <strong>on the derivative</strong>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># identical magnitude 3.0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">argmax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">abs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(x))              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2  — decided by the partial</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">argmax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">abs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.(x)))      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1  — first occurrence, real-BLAS semantics</span></span></code></pre></div><p>A partial is an infinitesimal and carries no magnitude information, so letting it decide means the answer depends on the seed direction. It matters because <strong><code>iamax</code> is the pivot-selection primitive in <code>getrf</code></strong>: a pivot chosen by perturbation direction can make the LU pivot sequence differ between the primal and the AD run on identical input, and forward-mode derivatives of a pivoted factorisation assume the sequence is locally constant. Nothing is lost by ignoring partials — the return type is an <code>Int</code>.</p><p><strong>Decision (user, 2026-09-12): value-only, first occurrence, matching real BLAS.</strong> <code>_l1v</code> is added so the scalar and SIMD paths agree.</p><h2 id="Performance-bar" tabindex="-1">Performance bar <a class="header-anchor" href="#Performance-bar" aria-label="Permalink to &quot;Performance bar {#Performance-bar}&quot;">​</a></h2><p>Not &quot;dual ≥ complex&quot; uniformly — that is too weak in places and unachievable in others. Honest per-vector op counts:</p><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">dual</th><th style="text-align:right;">complex</th></tr></thead><tbody><tr><td style="text-align:right;">nrm2</td><td style="text-align:right;">shuffle + FMA</td><td style="text-align:right;">FMA</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;">shuffle + flipsign + add</td><td style="text-align:right;">abs + add</td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">shuffle + abs</td><td style="text-align:right;">abs + shuffle + add</td></tr><tr><td style="text-align:right;">dot, axpy, scal</td><td style="text-align:right;">identical</td><td style="text-align:right;">identical</td></tr></tbody></table><p>Complex <code>asum</code> is <code>Σ\\|Re\\|+\\|Im\\|</code> (<code>core.jl:217-218</code>) — <strong>not</strong> the modulus — so it is already the minimal real kernel over 2n reals, and dual cannot beat it: dual must move data across the lane pair and complex need not. The bar is therefore:</p><ul><li><p><strong>equal</strong> to the twin at every n for dot/axpy/scal/copy/swap;</p></li><li><p><strong>strictly greater in L1/L2</strong> for iamax (dual drops one op; <code>simd_kernels.jl:1043-1050</code> measured one deleted op as +21% at n=1e3);</p></li><li><p><strong>equal past L2</strong> for nrm2/asum, and in-cache within the cost of the extra op — priced with <code>mca_report</code> before anyone calls it a limit.</p></li></ul><h2 id="Architecture" tabindex="-1">Architecture <a class="header-anchor" href="#Architecture" aria-label="Permalink to &quot;Architecture {#Architecture}&quot;">​</a></h2><p><code>PairAlgebra</code> as a type <em>hierarchy</em> was dropped: the largest win (nrm2) shares nothing with complex, so an abstraction spanning all ops would not have earned its place. What survives is a codegen-time <strong>multiply-rule tag</strong> on the three generated bodies where dual and complex differ only by constants or epilogue — <code>_dot_cmplx_simd</code>, <code>_axpy_cmplx_{phase,wide}!</code>, <code>_scal_cmplx_simd!</code>.</p><p>It earns that on <code>dot</code> (3× in cache, byte-identical complex body) and because every future complex arm — the <code>U = 8</code> band arm, a DRAM prefetch arm — then lands on dual for free. A separate copy would silently miss both.</p><p>The tag and its singletons live in <strong>PureBLAS, not the extension</strong>: a <code>@generated</code> body runs at the world age of its own definition, so a codegen hook defined later in an extension would be invisible inside the generator. The tag needs no ForwardDiff knowledge — it is <code>Val(:cplx)</code> / <code>Val(:dual)</code>, the same form the iamax scaffold uses, and it resolves to two codegen constants (<code>_pair_shuf</code>, the in-lane shuffle: swap-adjacent vs duplicate-even; <code>_pair_sgn</code>, the lane multiplier: <code>[−b, +b, …]</code> vs <code>[0, +b, …]</code>) plus, for dot, the epilogue. The complex entry names (<code>_dot_cmplx_simd</code>, <code>_axpy_cmplx_{simd,phase,wide}!</code>, <code>_scal_cmplx_simd!</code>) survive as <code>@inline</code> forwarders to the <code>:cplx</code> instantiation, so no complex caller changed.</p><p><code>Expr(:meta, :inline)</code> stays inside returned generator bodies; <code>@inline</code> does not propagate into <code>@generated</code> CodeInfo.</p><h2 id="The-extension" tabindex="-1">The extension <a class="header-anchor" href="#The-extension" aria-label="Permalink to &quot;The extension {#The-extension}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[weakdeps]  ForwardDiff = &quot;...&quot;</span></span>
<span class="line"><span>[extensions] PureBLASForwardDiffExt = &quot;ForwardDiff&quot;</span></span></code></pre></div><p>Five one-line methods and <strong>no kernels</strong>: <code>_pairalg</code>, <code>_pairreal</code>, <code>_parts</code>, <code>_mkpair</code>, <code>_l1v</code>, plus the layout assert. ForwardDiff never enters <code>[deps]</code>, so the <code>--trim</code> build never loads it and <code>libpureblas.so</code> is unaffected.</p><p><code>Tag</code> is never inspected. The only Duals the fast path constructs carry <code>x</code>&#39;s own tag, exactly as the scalar path does today via <code>convert</code>; a mixed-tag alpha fails in <code>convert</code> identically on both paths.</p><h2 id="Implementation-sequence" tabindex="-1">Implementation sequence <a class="header-anchor" href="#Implementation-sequence" aria-label="Permalink to &quot;Implementation sequence {#Implementation-sequence}&quot;">​</a></h2><p>Deliberately ordered so a complex regression can never be confounded with the dual work.</p><ol><li><p><strong>Complex only, no dual code.</strong> Parameterise <code>U</code> in <code>_axpy_cmplx_phase!</code> (currently hardcoded 4 at <code>simd_kernels.jl:471</code>, while real axpy has a <code>U = 8</code> band arm) — Derive <code>min(8, (_NVREG−4)÷3)</code>, which reproduces today&#39;s AVX2 code exactly. A/B at n=2e4/3e4/6e4 with real axpy at 6e4 as the L2-edge control. Route complex copy/swap off the scalar loop. Real-alpha zaxpy bypass, measured at n=1e3 and dropped if it costs. Add a <code>zscalc</code> bench row. Gate, commit.</p></li><li><p><strong>Extension + standalone dual kernels</strong>: routing, then nrm2 (the 13×), asum, iamax. No complex arithmetic kernel is touched.</p></li><li><p><strong>Tagged shared bodies</strong>, dot first, then axpy/scal. Each op its own commit, guarded by complex <code>code_native</code> byte-identity against the post-step-1 baseline plus an opcode-histogram equality test between the complex and dual instantiations. If complex moves by one instruction, that op ships as a copy under the histogram test instead.</p></li></ol><h2 id="What-this-does-NOT-fix" tabindex="-1">What this does NOT fix <a class="header-anchor" href="#What-this-does-NOT-fix" aria-label="Permalink to &quot;What this does NOT fix {#What-this-does-NOT-fix}&quot;">​</a></h2><p>Stated plainly because the complex gate gaps motivated the work and mostly are not complex-kernel gaps:</p><ul><li><p><strong>zscal is not a complex kernel problem.</strong> The gate row scales by <code>1.0000001 + 0im</code> (<code>bench/plots.jl:1231</code>), and <code>_scal!</code> routes a real alpha to the real kernel over 2n reals (<code>level1.jl:33-37</code>). Every zscal cell is the real-scal L2/L3-edge notch. <code>_scal_cmplx_simd!</code> has <strong>no gate coverage at all</strong> — hence the new <code>zscalc</code> row in step 1.</p></li><li><p><strong>zaxpy past L3 on Zen5 tracks real axpy</strong> (0.921/0.919 vs 0.925/0.949 at n=3e5/1e6) — memory system, not algebra.</p></li><li><p><strong>zdotu Zen5 at n=1e6</strong> is a DRAM-regime question for a roofline decomposition, not a kernel.</p></li></ul><p>The one genuinely complex-specific cell is <strong>zaxpy@3e4</strong> (Zen4 0.963, Zen5 0.834), which step 1 targets.</p><p>⚠ Zen5 (neuromancer) is not gate-authoritative: its lock drops on power change, and it reads <strong>FP256</strong> (<code>test/autotune_tests.jl:21-23</code> — Strix/Krackan, <code>fpw = 32</code>, double-pumped, lands with Zen4). Do not build a width argument on &quot;Zen5 is native-512&quot;; that is a retracted claim from an old family lookup.</p><h2 id="Implementation-notes-steps-1-and-2,-2026-09-12" tabindex="-1">Implementation notes (steps 1 and 2, 2026-09-12) <a class="header-anchor" href="#Implementation-notes-steps-1-and-2,-2026-09-12" aria-label="Permalink to &quot;Implementation notes (steps 1 and 2, 2026-09-12) {#Implementation-notes-steps-1-and-2,-2026-09-12}&quot;">​</a></h2><p>Measured after step 2, same method as the baseline table above (wintermute, Chairmarks median of 6 rounds, plots.jl regime, <code>bench/probes/dual_twins.jl</code>) — dual GB/s ÷ complex twin:</p><p>⚠ <strong>READ THE ALPHA COLUMN BEFORE THE RATIO.</strong> axpy/scal have two regimes and only one of them is implemented. Step 2 routes a <strong>real</strong> alpha to the real kernel over 2n reals; a <strong>dual</strong> alpha (nonzero partial) still takes the generic scalar loop, because that is step 3. The first draft of this table printed the real-alpha 1.00 against a dual-alpha baseline of 0.82, which reads as &quot;axpy is done&quot; and would argue a reader out of step 3. Measured directly (axpy, n=1e3 / 1e4):</p><table tabindex="0"><thead><tr><th style="text-align:right;">alpha</th><th style="text-align:right;">dual GB/s</th><th style="text-align:right;">complex GB/s</th><th style="text-align:right;">D/C</th></tr></thead><tbody><tr><td style="text-align:right;">real (<code>Dual(1.7, 0.0)</code>) — bypass applies</td><td style="text-align:right;">117.1 / 129.8</td><td style="text-align:right;">117.1 / 130.2</td><td style="text-align:right;"><strong>1.00 / 1.00</strong></td></tr><tr><td style="text-align:right;">dual (<code>Dual(1.7, 0.3)</code>) — generic, step 3</td><td style="text-align:right;">95.8 / 103.5</td><td style="text-align:right;">116.8 / 129.8</td><td style="text-align:right;"><strong>0.82 / 0.80</strong></td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">n=1e3</th><th style="text-align:right;">n=1e4</th><th style="text-align:right;">n=1e5</th><th style="text-align:right;">n=1e6</th><th style="text-align:right;">before</th></tr></thead><tbody><tr><td style="text-align:right;">axpy (real α)</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.01</td><td style="text-align:right;">1.01</td><td style="text-align:right;">1.02</td><td style="text-align:right;">— (new path)</td></tr><tr><td style="text-align:right;">axpy (dual α)</td><td style="text-align:right;">0.82</td><td style="text-align:right;">0.80</td><td style="text-align:right;">1.01</td><td style="text-align:right;">1.00</td><td style="text-align:right;">0.82 0.80 1.03 1.00 — <strong>unchanged, step 3</strong></td></tr><tr><td style="text-align:right;">scal (real α)</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.01</td><td style="text-align:right;">1.01</td><td style="text-align:right;">— (new path)</td></tr><tr><td style="text-align:right;">scal (dual α)</td><td style="text-align:right;">0.69</td><td style="text-align:right;">0.66</td><td style="text-align:right;">0.90</td><td style="text-align:right;">0.94</td><td style="text-align:right;">0.69 0.65 0.77 0.99 — <strong>unchanged, step 3</strong></td></tr><tr><td style="text-align:right;">copy</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.03</td><td style="text-align:right;">1.01</td><td style="text-align:right;">1.01</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;">swap</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.05</td><td style="text-align:right;">0.99</td><td style="text-align:right;">1.02</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;">dot</td><td style="text-align:right;">0.20</td><td style="text-align:right;">0.34</td><td style="text-align:right;">0.40</td><td style="text-align:right;">0.58</td><td style="text-align:right;">0.37 0.34 0.49 0.92 (generic loop; step 3)</td></tr><tr><td style="text-align:right;">asum</td><td style="text-align:right;">0.60</td><td style="text-align:right;">0.99</td><td style="text-align:right;">0.98</td><td style="text-align:right;">1.01</td><td style="text-align:right;">0.21 0.18 0.23 0.61</td></tr><tr><td style="text-align:right;">iamax</td><td style="text-align:right;">1.17</td><td style="text-align:right;">1.20</td><td style="text-align:right;">1.20</td><td style="text-align:right;">1.18</td><td style="text-align:right;">0.37 0.29 0.29 0.36</td></tr><tr><td style="text-align:right;">nrm2</td><td style="text-align:right;">0.73</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.00</td><td style="text-align:right;">0.97</td><td style="text-align:right;">0.07 0.06 0.08 0.20</td></tr></tbody></table><p>What <code>@code_native</code> settled: <code>dupEven</code> emits <code>vmovddup</code> (in-lane, one per vector, no cross-lane shuffle); nrm2 is <code>vmovddup</code> + FMA. SIMD.jl&#39;s <code>flipsign</code> lowered to <strong>two</strong> ops (<code>vpmovq2m</code> + masked <code>vxorpd</code>) and put asum at 0.48× in L1; written as <code>v ⊻ (dupEven(v) &amp; signmask)</code> it is one <code>vpternlogq</code> (<code>_flipsign_bits</code>), 0.60× in L1 and parity from L2. In-L1 nrm2/asum sit at the extra op priced above; not yet run through <code>mca_report</code>.</p><p><strong>Deviation from this design — nrm2&#39;s overflow fallback.</strong> The page said &quot;falls back to the existing Dual lassq loop&quot;. The 1e200-scale test it prescribed showed that loop is numerically wrong there: <code>_lassq</code> divides Duals and ForwardDiff&#39;s quotient rule squares the ~1e200 denominator, so the partial is garbage (one input: −1.66 vs analytic −1.39; <code>LinearAlgebra.norm</code> over Duals — the intended oracle — gave −1.47, broken the same way). The overflow path is now <code>_nrm2_dual_scaled</code>: real lassq over the values, partial <code>Σ (x_v/scale)·x_p / √ssq</code>. The generic scalar loop for <code>N ≠ 1</code> / nested duals keeps the old behaviour. The test oracle at extreme scale is the analytic partial, not <code>ForwardDiff.derivative</code> on <code>norm</code>.</p><p>Step 1 findings: the phase-kernel <code>U</code> parameterisation is byte-identical at <code>U=4</code> (code_native, 202 = 202 instructions); <code>U=8</code> on AVX-512 is +1.3% [1.004, 1.024] at n=3e4 and a tie at 2e4/6e4, so it does not by itself close zaxpy@3e4. The real-alpha zaxpy bypass costs nothing measurable (compare-not-taken 0.990 [0.961, 1.025] at n=1e3) and wins 8.7% with a real alpha. LLVM does not vectorize the scalar complex copy/swap loops (memmove / memcpy+memmove); routed onto the real kernels: copy 1.9× in L1, level from L2; swap 2.4–3.1× everywhere. The complex iamax scaffold is byte-identical after taking the magnitude as a codegen parameter (352 = 352 / 426 = 426 instructions, F64/F32).</p><h2 id="Implementation-notes-step-3,-2026-09-12" tabindex="-1">Implementation notes (step 3, 2026-09-12) <a class="header-anchor" href="#Implementation-notes-step-3,-2026-09-12" aria-label="Permalink to &quot;Implementation notes (step 3, 2026-09-12) {#Implementation-notes-step-3,-2026-09-12}&quot;">​</a></h2><p>The three tagged bodies landed as three commits (dot, axpy, scal), each gated by <code>bench/probes/dual_step3_native.jl</code>: the complex instantiation&#39;s normalised <code>code_native</code> diffed against a pre-edit dump (20 cells — five bodies × F64/F32 × <code>Vector</code>/<code>Ptr</code> carrier), plus an opcode histogram of the <strong>main SIMD loop</strong> of the complex vs dual instantiation. Both gates held for all three ops, so <strong>nothing shipped as a copy</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">body</th><th style="text-align:right;">complex code_native, before = after (F64 vec / ptr; F32 vec / ptr)</th><th style="text-align:right;">main-loop histogram, complex vs dual</th></tr></thead><tbody><tr><td style="text-align:right;"><code>_dot_pair_simd</code> dotu / dotc</td><td style="text-align:right;">201 = 201 / 199 = 199 ; 219 = 219 / 217 = 217 (dotc 232 / 230 ; 219 / 217)</td><td style="text-align:right;">46 = 46 (F64), 45 = 45 (F32), raw-equal</td></tr><tr><td style="text-align:right;"><code>_axpy_pair_phase!</code></td><td style="text-align:right;">213 = 213 / 209 = 209 ; 238 = 238 / 234 = 234</td><td style="text-align:right;">46 = 46 / 45 = 45, equal modulo 8 <code>vshufpd</code> ↔ 8 <code>vmovddup</code></td></tr><tr><td style="text-align:right;"><code>_axpy_pair_wide!</code></td><td style="text-align:right;">226 = 226 / 222 = 222 ; 251 = 251 / 247 = 247</td><td style="text-align:right;">54 = 54 / 53 = 53, same</td></tr><tr><td style="text-align:right;"><code>_scal_pair_simd!</code></td><td style="text-align:right;">292 = 292 / 289 = 289 ; 257 = 257 / 254 = 254</td><td style="text-align:right;">46 = 46 / 45 = 45, same</td></tr></tbody></table><p>The histogram is taken over the loop, not the whole function, because the epilogue is per-algebra by design (dot drops the ε² lane; the scalar tails differ) and because LLVM happens to auto-vectorise the complex scalar tail of dotu/axpy/scal (<code>vaddsubpd</code>) and not the dual one — tail code, not the kernel. The loop histogram is also a <code>@testitem</code> (<code>DualNative</code>), with a positive control (an FMA loop was found) and a negative one (the histogram is not blind).</p><p>Measured with a <strong>dual alpha</strong> (<code>bench/probes/dual_twins3.jl</code>: axpy <code>Dual(1.7, 0.3)</code> vs <code>1.7 + 0.3im</code>, scal <code>Dual(1.0000001, 1e‑7)</code> vs <code>1.0000001 + 1e‑7im</code>, so both arms run the tagged complex-layout kernel and neither takes the real-alpha bypass; Chairmarks median of 6 rounds, wintermute, dual GB/s ÷ complex twin, two samples):</p><table tabindex="0"><thead><tr><th style="text-align:right;">op</th><th style="text-align:right;">n=1e3</th><th style="text-align:right;">n=1e4</th><th style="text-align:right;">n=1e5</th><th style="text-align:right;">n=1e6</th><th style="text-align:right;">before (generic loop)</th></tr></thead><tbody><tr><td style="text-align:right;">axpy (dual α)</td><td style="text-align:right;">0.98–0.99 (188.6 vs 191.8 GB/s)</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.00–1.01</td><td style="text-align:right;">1.00–1.02</td><td style="text-align:right;">0.61 0.80 0.93 1.03</td></tr><tr><td style="text-align:right;">scal (dual α)</td><td style="text-align:right;">0.99 (166.5 vs 168.2)</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.01</td><td style="text-align:right;">0.99</td><td style="text-align:right;">0.62 0.64 0.72 0.83</td></tr><tr><td style="text-align:right;">dot</td><td style="text-align:right;">1.00 (152.5 vs 152.4)</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.01</td><td style="text-align:right;">1.00</td><td style="text-align:right;">0.20 0.34 0.40 0.58</td></tr></tbody></table><p>The &quot;before&quot; row here is the true dual-alpha baseline against the true complex kernel — the step-2 table&#39;s complex arm used a real alpha and so measured the real-axpy bypass (117 GB/s at n=1e3), not <code>_axpy_cmplx_wide!</code> (192 GB/s). Two things follow. First, the only residual is the ~1% at n=1e3 on axpy/scal, where the loop differs by one mnemonic (<code>vmovddup</code> for duplicate-even vs <code>vshufpd</code> for the swap) — it moved 0.98→0.99 between two samples and has not been chased. Second, an observation outside this step&#39;s scope: at n=1e3 the real-alpha bypass (real axpy over 2n reals, 117 GB/s) is markedly slower than the complex wide arm on the same bytes (192 GB/s), so the bypass may be the wrong arm in L1; not measured further here.</p><p>Design on contact: the doc&#39;s &quot;differ only by constants&quot; held literally for axpy/scal — the tag resolves to a shuffle pattern and a sign vector and nothing else in the loop changes. For dot it held for the loop and the epilogue is per-algebra (value = <code>pfld[1]</code> alone; the discarded <code>Σ x_p y_p</code> lane must not even be multiplied by zero, since it may be <code>Inf</code>). The dual dot returns the bare <code>(value, partial)</code> tuple and <code>_dotu</code>/<code>_dotc</code> wrap it with <code>_mkpair</code>, so the kernel never sees a Dual type; <code>_pairv(x)</code> (the real type under a pair vector, static) was the one accessor the routing needed beyond the five. The NaN-hygiene item now covers the dual-alpha axpy/scal paths, which is why duplicate-even rather than the swap was the right shuffle for the dual arm: with the swap, an infinite partial would put <code>0·Inf</code> on the value lane, which the generic loop keeps finite.</p>`,73)])])}const u=e(o,[["render",d]]);export{p as __pageData,u as default};
